const raw = $input.first().json || {};
const data = (raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query)) ? raw.query : raw;

const brand = String(data.brand || raw.brand || '').trim();
const category = String(data.category || raw.category || '').trim();
const limitRaw = parseInt(data.limit || raw.limit, 10);
const limit = Math.max(1, Math.min(Number.isFinite(limitRaw) ? limitRaw : 10, 20));

return [{ json: { brand, category, limit } }];

const rows = $input.all().map(i => i.json);
const input = $('Normalize Input').first().json;
const validRows = rows.filter(r => r && r.product_sku);
const limited = validRows.slice(0, input.limit || 10);

if (!limited.length) {
  return [{ json: { found: false, count: 0, total_found: 0, message: `No hay productos activos para brand='${input.brand}' category='${input.category}'.`, query: input, results: [] } }];
}

return [{ json: {
  found: true,
  count: limited.length,
  total_found: validRows.length,
  query: input,
  results: limited.map(r => ({
    sku: r.product_sku,
    title: r.title,
    brand: r.brand,
    category: r.category,
    price: r.price_amount ? `${r.price_amount} ${r.currency || 'USD'}` : 'consultar',
    stock: r.stock_status,
    image_url: r.image_url || null,
    promo: r.promo_text || null
  }))
} }];
